{
  "analysis": "The ffmpeg loop issue is caused by ffmpeg reading queued stdin commands. We need use `-nostdin` flag. Only 195 prompt crops were created before interruption. I should re-extract all prompt crops in a single ffmpeg command from the original video, with `-nostdin` to prevent it from consuming subsequent commands.",
  "plan": "Re-extract prompt-line crops from the original video in one ffmpeg command with -nostdin, cropping the prompt region (around y=645, x=120 in the 1280x720 original). Then verify the crop count and OCR quality on samples.",
  "commands": [
    {
      "keystrokes": "rm -rf /app/prompts2; mkdir -p /app/prompts2\n",
      "duration": 0.1
    },
    {
      "keystrokes": "ffmpeg -nostdin -hide_banner -loglevel error -y -i /app/video.mp4 -vf \"fps=2,crop=1000:45:115:645\" /app/prompts2/frame_%04d.png\n",
      "duration": 5.0
    },
    {
      "keystrokes": "ls /app/prompts2 | wc -l\n",
      "duration": 0.1
    },
    {
      "keystrokes": "tesseract /app/prompts2/frame_0001.png stdout --psm 7 2>/dev/null; tesseract /app/prompts2/frame_0061.png stdout --psm 7 2>/dev/null; tesseract /app/prompts2/frame_0121.png stdout --psm 7 2>/dev/null\n",
      "duration": 1.0
    }
  ]
}
